INSERT INTO `termline` VALUES (14604,3624,7,NULL,'<p><strong>Process</strong></p><p>Projecting the part of the bone</p>',2,0,NULL,1,'2024-12-09 11:56:35',44,'2024-12-11 06:26:27'),(14608,3624,13,NULL,'<p>Superiorly-anteriorly process (highest point) of the Scapula that articulates with the Clavicle to form the AcromioClavicular (AC) Joint.</p>',3,0,NULL,1,'2024-12-09 11:56:35',44,'2024-12-11 06:27:17'),(14642,3632,7,NULL,'Arcuate',2,0,NULL,1,'2024-12-09 11:56:35',NULL,NULL),(14643,3632,8,NULL,'Ligament bent like a bow in the back of the knee connecting the fibular posterior head to the posterior capsule of the knee.',5,1,NULL,1,'2024-12-09 11:56:35',NULL,NULL),(14644,3632,9,NULL,'<ul><li><b><i>Arcus</i></b><br>(L. n.), <i>\"the bow\"</i></b> in bow & arrow </li><li><b><i>Arcuatus</i></b><br>(L. adj.), figuratively, <i>“arched, bent like a bow”</i></li></ul> \r\n',6,0,NULL,1,'2024-12-09 11:56:35',NULL,NULL),(14645,3632,13,NULL,'<ul><li><b>Popliteal Ligament</b><br>Back of knee</li></ul>',3,0,NULL,1,'2024-12-09 11:56:35',NULL,NULL),(15082,3624,8,NULL,'<p><strong><em>Akros</em></strong> (Gr. adj.), highest<strong><em> </em></strong></p><p><strong><em>Omos</em></strong> (Gr. n.), shoulder</p>',4,0,NULL,44,'2024-12-11 06:28:31',NULL,NULL),(15083,3624,9,NULL,'<p><strong><em>Acromium</em></strong>,</p><p>Metaphorically, <em>“The highest point of shoulder</em>”</p><p><br></p><p>comp., <strong><em><u>Acro- + Om- + -ium</u></em></strong></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong><em>Acro-</em></strong><em> derived from </em><strong><em>Akros</em></strong></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong><em>Om-</em></strong><em> derived from </em><strong><em>Omos</em></strong></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong><em>-ium</em></strong>, L. suffix, forms noun.&nbsp;</p>',5,0,NULL,44,'2024-12-11 06:30:27',NULL,NULL),(15084,3624,12,NULL,'<p>ACROMEGALY – SKELETAL SYSTEM</p><p>ACROSOME – REPRODUCTIVE SYSTEM</p><p><br></p